tool_calls:
grep -c -E '^[^ ]+ [^ ]+ /healthz(\?[^ ]*)? [^ ]+ [0-9]+ms$' /home/eval/logs/access.log
awk 'NF==5 && $5~/^[0-9]+ms$/{print $3}' /home/eval/logs/access.log | sort | uniq -c
# count healthz/static normalized excluded
awk '
{
  line=$0
  if (line ~ /^[^ ]+ [^ ]+ [^ ]+ [^ ]+ [^ ]+$/) {
    n=split(line,f," ")
    if(n==5 && f[5]~/^[0-9]+ms$/) {
      p=f[3]; q=index(p,"?"); if(q>0)p=substr(p,1,q-1)
      if(p!="/"&&substr(p,length(p),1)=="/")p=substr(p,1,length(p)-1)
      print p
    } else print "INVALID:"line > "/dev/stderr"
  } else print "BADFIELDS:"line > "/dev/stderr"
}' /home/eval/logs/access.log 2>/tmp/bad.txt | sort | uniq -c
echo "---bad---"; cat /tmp/bad.txt
echo "---total valid---"
awk '
{
  line=$0
  if (line ~ /^[^ ]+ [^ ]+ [^ ]+ [^ ]+ [^ ]+$/) {
    n=split(line,f," ")
    if(n==5 && f[5]~/^[0-9]+ms$/) c++
  }
}END{print c}' /home/eval/logs/access.log

